+            .join("../../assets/themes")
+            .join(file);
+        let parsed = theme_files::load(&path).unwrap_or_else(|e| panic!("{file}: {e}"));
+        assert_eq!(theme::status_h(&parsed.tokens), 22.0, "{file}: default status_h");
+        assert_eq!(parsed.tokens.window_margin, 6.0, "{file}: default window_margin");
